package main

import (
	"fmt"
	"net"
)

func getURLToVisit(domain, subdomainPrefix string) string {
	if subdomainPrefix == "" || subdomainPrefix == "." || subdomainPrefix == "www" {
		return "https://" + domain
	}
	return "https://" + subdomainPrefix + "." + domain
}

func main() {
	fmt.Println(getURLToVisit("example.com", "subdomain"))   // Expected: https://subdomain.example.com
	fmt.Println(getURLToVisit("example.com", "a.b"))          // Expected: https://a.b.example.com
	fmt.Println(getURLToVisit("example.com", ""))             // Expected: https://example.com
	fmt.Println(getURLToVisit("example.com", "."))            // Expected: https://example.com
	fmt.Println(getURLToVisit("example.com", "www"))          // Expected: https://example.com
}
